#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")"
export LC_ALL=C.UTF-8
ROOT=/mise/extra-tools/android-reverse
JAVA="$ROOT/usr/lib/jvm/java-21-openjdk-amd64/bin"
export LD_LIBRARY_PATH="$ROOT/usr/lib/x86_64-linux-gnu/android:$ROOT/usr/lib/x86_64-linux-gnu:$ROOT/usr/lib/7zip:$ROOT/usr/lib"
CONFIG_FILE="src/org/oppo/drawergroups/BuildConfig.java"

write_config() {
    local enable="$1" px="$2"
    cat > "$CONFIG_FILE" <<EOF
package org.oppo.drawergroups;

/** Build-time configuration. Regenerated by build.sh for each variant. */
public final class BuildConfig {
    /** true: enable the A-Z letter bar spacing hook; false: keep the stock spacing. */
    public static final boolean ENABLE_SPACING_HOOK = $enable;
    /** Spacing in raw pixels passed to COUITouchSearchView.setItemSpacing(). Stock is 4. */
    public static final int SPACING_PX = $px;

    private BuildConfig() {}
}
EOF
}

build_variant() {
    local out="$1" enable="$2" px="$3"
    echo "==> Building $out (spacing hook=$enable, px=$px)"
    write_config "$enable" "$px"
    rm -rf build/classes build/dex build/unsigned.apk build/aligned.apk
    mkdir -p build/stubs build/classes build/dex build/tests build/out
    "$JAVA/javac" --release 8 -d build/stubs $(find stubs -name '*.java')
    "$JAVA/javac" --release 8 -cp build/stubs:"$ROOT/android.jar" -d build/classes $(find src -name '*.java')
    "$JAVA/javac" --release 8 -cp build/classes:build/stubs -d build/tests $(find tests -name '*.java')
    "$JAVA/java" -cp build/classes:build/tests GroupSelectorTest
    "$JAVA/java" -cp build/classes:build/tests RowPlanTest
    "$JAVA/java" -cp build/classes:build/stubs:build/tests:"$ROOT/android.jar" HookTest
    "$JAVA/java" -cp "$ROOT/r8.jar" com.android.tools.r8.D8 --min-api 26 --output build/dex $(find build/classes -name '*.class')
    "$ROOT/usr/bin/aapt" package -f -M AndroidManifest.xml -S res -I "$ROOT/usr/share/android-framework-res/framework-res.apk" -A assets -F build/unsigned.apk
    (cd build/dex && zip -q -u ../unsigned.apk classes.dex)
    "$ROOT/usr/bin/zipalign" -f 4 build/unsigned.apk build/aligned.apk
    if [ ! -f build/signing-key.p12 ]; then
        "$JAVA/keytool" -genkeypair -keystore build/signing-key.p12 -storetype PKCS12 -storepass android -keypass android -alias drawer -keyalg RSA -keysize 3072 -validity 10000 -dname 'CN=OPPO Drawer Groups Local Build' >/dev/null 2>&1
    fi
    "$JAVA/java" -jar "$ROOT/usr/share/java/apksigner.jar" sign --ks build/signing-key.p12 --ks-pass pass:android --key-pass pass:android --out "build/out/$out" build/aligned.apk
    "$JAVA/java" -jar "$ROOT/usr/share/java/apksigner.jar" verify --min-sdk-version 26 "build/out/$out" >/dev/null
    echo "==> OK: build/out/$out"
    sha256sum "build/out/$out"
}

mkdir -p build/out

# 版本一 / Variant 1: 原始间距（不修改字母栏，保持原厂 4px）/ stock spacing (no hook)
build_variant "OPPO-Drawer-Groups-StockSpacing.apk" false 4

# 版本二 / Variant 2: 间距修改版（字母栏间距 8px）/ spacing-modified version (8px)
build_variant "OPPO-Drawer-Groups-Spacing8px.apk" true 8

# 还原源码配置为默认（间距修改版 8px），保持仓库源码整洁
# Restore the tracked source config to the default (spacing version, 8px)
write_config true 8
